sys_script_include.script:
var DateSignup = Class.create();
DateSignup.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkUserRegistration: function() {
        var userId = this.getParameter('sysparm_userId');
        var trainingScheduleId = this.getParameter('sysparm_trainingScheduleId');
        var trainingDate = this.getParameter('sysparm_trainingDate');

        var gr = new GlideRecord('x_1593191_cooknow_registration');
        gr.addQuery('training', trainingScheduleId);  
        gr.addQuery('student_name', userId);  
        gr.addQuery('date', trainingDate);  
        gr.query();

        if (gr.next()) {
            return true;  
        } else {
            return false;  
        }
    },

    type: 'DateSignup'
});
